class WorldError(Exception):
    """Something in a world (or a gesture on it) that the bench cannot accept."""

    def __init__(self, message, path=None, line=None):
        super().__init__(message)
        self.message = message
        self.path = path
        self.line = line

    def __str__(self):
        where = ":".join(str(part) for part in (self.path, self.line) if part)
        return f"{where}: {self.message}" if where else self.message

"""Exploration: a breadth-first walk through every state a world allows.

Breadth-first order means the first time anything is seen -- a broken beam,
a probe's answer, a stuck state -- it is seen at the end of a shortest path.
"""

from __future__ import annotations

from collections import Counter, deque
from types import SimpleNamespace

from .errors import WorldError
from .expr import suggest

LIMIT = 200_000
KEEP_BREACHES = 20


class Move:
    """One attempted step: free, refused by a boundary, or a breach of a domain."""

    __slots__ = ("label", "action", "target", "refused", "breach")

    def __init__(self, label, action, target, refused=None, breach=None):
        self.label, self.action, self.target = label, action, target
        self.refused, self.breach = refused, breach


def moves_from(world, state, refusals, disabled=None):
    env = world.env(state)
    was = None
    moves = []
    for action in world.actions:
        for label, params in action.instances:
            aenv = {**env, **params} if params else env
            if action.guard is not None and not action.guard.test(aenv):
                if disabled is not None:
                    disabled.append(label)
                continue
            new = list(state)
            for i, expr in action.assigns:
                new[i] = expr(aenv)
            breach = next(((world.vars[i].name, new[i]) for i, _ in action.assigns
                           if not world.vars[i].accepts(new[i])), None)
            if breach:
                moves.append(Move(label, action.name, None, breach=breach))
                continue
            target = tuple(new)
            refused = None
            if refusals:
                if was is None:
                    was = SimpleNamespace(**env)
                tenv = world.env(target)
                tenv["via"], tenv["was"] = action.name, was
                refused = next((r for r in refusals if r.expr.test(tenv)), None)
            moves.append(Move(label, action.name, target, refused=refused))
    return moves


def at_rest(world, state):
    env = world.env(state)
    return any(rest.expr.test(env) for rest in world.rests)


class Exploration:
    def __init__(self, world, refusals, initial, limit):
        self.world = world
        self.refusals = refusals
        self.initial = initial
        self.limit = limit
        self.parent = {}           # state -> (previous state, label), or None if initial
        self.depth = {}
        self.moves = 0             # free transitions seen, including into known states
        self.fired = Counter()     # action -> free transitions
        self.pressed = Counter()   # refusal -> moves it turned away
        self.first_press = {}      # refusal -> (state, label, target), shortest first
        self.breach_count = 0
        self.breaches = []         # (state, label, var, value), shortest first
        self.still = []            # (state, refusals that walled it in)
        self.beam_breaks = {}      # beam -> first state where it is false
        self.probe_hits = {}       # probe -> first state where it is true
        self.found = None          # the state an `until` search stopped at
        self.complete = True       # every reachable state was seen

    @property
    def reachable(self):
        return len(self.parent)

    @property
    def max_depth(self):
        return max(self.depth.values(), default=0)

    def stuck(self):
        return [(s, walls) for s, walls in self.still if not at_rest(self.world, s)]

    def trace(self, state):
        steps = []
        while True:
            link = self.parent[state]
            if link is None:
                steps.append((None, state))
                return steps[::-1]
            previous, label = link
            steps.append((label, state))
            state = previous


def explore(world, extra_inits=(), without=(), limit=LIMIT, until=None):
    """Walk every reachable state, or stop at the first one where `until` holds."""
    names = [r.name for r in world.refusals]
    for name in without:
        if name not in names:
            raise WorldError(f"{world.name} has no refusal `{name}`{suggest(name, names)}")
    refusals = [r for r in world.refusals if r.name not in without]
    look = Exploration(world, refusals, world.initial_states(extra_inits), limit)
    queue = deque()

    def discover(state, link):
        look.parent[state] = link
        look.depth[state] = 0 if link is None else look.depth[link[0]] + 1
        queue.append(state)
        env = world.env(state)
        for beam in world.beams:
            if beam.name not in look.beam_breaks and not beam.expr.test(env):
                look.beam_breaks[beam.name] = state
        for probe in world.probes:
            if probe.name not in look.probe_hits and probe.expr.test(env):
                look.probe_hits[probe.name] = state
        if until is not None and until.test(env):
            look.found = state
            look.complete = False
            return True
        return False

    for state in look.initial:
        if state not in look.parent and discover(state, None):
            return look

    while queue:
        state = queue.popleft()
        free, walls = 0, []
        for move in moves_from(world, state, refusals):
            if move.breach:
                look.breach_count += 1
                if len(look.breaches) < KEEP_BREACHES:
                    look.breaches.append((state, move.label) + move.breach)
                continue
            if move.refused:
                name = move.refused.name
                look.pressed[name] += 1
                look.first_press.setdefault(name, (state, move.label, move.target))
                walls.append(name)
                continue
            free += 1
            look.moves += 1
            look.fired[move.action] += 1
            if move.target in look.parent:
                continue
            if len(look.parent) >= limit:
                look.complete = False
                continue
            if discover(move.target, (state, move.label)):
                return look
        if free == 0:
            look.still.append((state, sorted(set(walls))))
    return look

"""Expressions: a small, checked subset of Python expression syntax.

An expression is parsed with `ast`, walked against a whitelist, checked
against the names and domains the world declares, and only then compiled.
Nothing outside the whitelist can run: no builtins, no attribute access
except `was.<var>`, no calls except min/max/abs.
"""

from __future__ import annotations

import ast
import difflib
import re

from .errors import WorldError
from .values import describe_domain, fmt_value, in_domain

FUNCS = {"min": min, "max": max, "abs": abs}
CONSTS = {"true": True, "false": False, "True": True, "False": False}
RESERVED = set(FUNCS) | set(CONSTS) | {"via", "was"}

_GLOBALS = {"__builtins__": {}, **FUNCS, **CONSTS}
_BINOPS = (ast.Add, ast.Sub, ast.Mult, ast.FloorDiv, ast.Mod)
_CMPOPS = (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.In, ast.NotIn)
_UNOPS = (ast.Not, ast.USub, ast.UAdd)


class Scope:
    """The names an expression may use, and the values each can hold."""

    def __init__(self, vars, params=None, refusal=False):
        self.vars = vars              # name -> domain tuple
        self.params = params or {}    # name -> domain tuple
        self.refusal = refusal        # refusals may also use `via` and `was.<var>`

    def domain_of(self, node):
        if isinstance(node, ast.Name):
            return self.params.get(node.id, self.vars.get(node.id))
        if _is_was(node):
            return self.vars.get(node.attr)
        return None

    def names(self):
        known = set(self.vars) | set(self.params) | {"true", "false"}
        return known | {"via"} if self.refusal else known

    def symbols(self):
        return {v for d in list(self.vars.values()) + list(self.params.values())
                for v in d if isinstance(v, str)}


class Expr:
    """A checked, compiled expression. Call it with an environment of names."""

    __slots__ = ("src", "tree", "what", "path", "line", "_code")

    def __init__(self, src, tree, code, what, path, line):
        self.src, self.tree, self.what = src, tree, what
        self.path, self.line, self._code = path, line, code

    def __call__(self, env):
        try:
            return eval(self._code, _GLOBALS, env)
        except Exception as exc:  # the world's own arithmetic or comparison failed
            raise WorldError(
                f"{self.what} `{self.src}` failed with {type(exc).__name__}: {exc} "
                f"(where {_describe_env(env)})", self.path, self.line) from None

    def test(self, env):
        value = self(env)
        if value is True or value is False:
            return value
        raise WorldError(
            f"{self.what} `{self.src}` gave {value!r}, but it must be true or false "
            f"(where {_describe_env(env)})", self.path, self.line)


def compile_expr(src, scope, what, path=None, line=None):
    src = src.strip()
    if not src:
        raise WorldError(f"{what} is empty", path, line)
    try:
        tree = ast.parse(src, mode="eval")
    except SyntaxError as exc:
        hint = ""
        if re.search(r"(?<![=!<>])=(?!=)", src):
            hint = " (to compare, write ==; a single = only assigns, after ->)"
        raise WorldError(f"cannot read {what} `{src}`: {exc.msg}{hint}", path, line) from None
    _Checker(scope, what, path, line).check(tree.body)
    code = compile(tree, f"<{what}>", "eval")
    return Expr(src, tree.body, code, what, path, line)


def literal_outcomes(node):
    """The literal values an expression can produce, where that is visible."""
    if isinstance(node, ast.Constant):
        return [node.value]
    if isinstance(node, ast.IfExp):
        return literal_outcomes(node.body) + literal_outcomes(node.orelse)
    return []


def suggest(name, candidates):
    close = difflib.get_close_matches(name, sorted(candidates), n=1)
    return f" (did you mean `{close[0]}`?)" if close else ""


def _is_was(node):
    return (isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name)
            and node.value.id == "was")


def _describe_env(env):
    shown = [f"{k}={fmt_value(v)}" for k, v in env.items() if k not in ("via", "was")]
    if "via" in env:
        shown.append(f"via={env['via']}")
    return " ".join(shown)


class _Checker:
    def __init__(self, scope, what, path, line):
        self.scope, self.what, self.path, self.line = scope, what, path, line

    def fail(self, message):
        raise WorldError(f"in {self.what}: {message}", self.path, self.line)

    def check(self, node):
        method = getattr(self, "_" + type(node).__name__, None)
        if method is None:
            self.fail(f"`{ast.unparse(node)}` is not part of the world language")
        method(node)

    def _BoolOp(self, node):
        for value in node.values:
            self.check(value)

    def _UnaryOp(self, node):
        if not isinstance(node.op, _UNOPS):
            self.fail(f"`{ast.unparse(node)}`: only `not` and unary minus are available")
        self.check(node.operand)

    def _BinOp(self, node):
        if isinstance(node.op, ast.Div):
            self.fail("`/` makes fractions and worlds hold whole numbers; use `//`")
        if not isinstance(node.op, _BINOPS):
            self.fail(f"`{ast.unparse(node)}`: the arithmetic here is + - * // %")
        for side in (node.left, node.right):
            if self._textual(side):
                self.fail(f"`{ast.unparse(node)}`: arithmetic is for numbers, "
                          f"and `{ast.unparse(side)}` is a name")
        self.check(node.left)
        self.check(node.right)

    def _Compare(self, node):
        for op in node.ops:
            if isinstance(op, (ast.Is, ast.IsNot)):
                self.fail("`is` compares identity; use == or !=")
            if not isinstance(op, _CMPOPS):
                self.fail(f"`{ast.unparse(node)}` uses a comparison the language lacks")
        self.check(node.left)
        for right in node.comparators:
            self.check(right)
        left = node.left
        for op, right in zip(node.ops, node.comparators):
            if isinstance(op, (ast.In, ast.NotIn)) and not isinstance(
                    right, (ast.Set, ast.Tuple, ast.List)):
                self.fail(f"`{ast.unparse(node)}`: `in` asks about a collection written "
                          "out in full, like n in {1, 2}")
            self._literals(left, op, right)
            left = right

    def _IfExp(self, node):
        self.check(node.test)
        self.check(node.body)
        self.check(node.orelse)

    def _Constant(self, node):
        if not isinstance(node.value, (int, str)):  # bool is an int
            self.fail(f"{node.value!r} cannot live in a world; "
                      "use whole numbers, quoted names, or true/false")

    def _Tuple(self, node):
        for elt in node.elts:
            self.check(elt)

    _List = _Set = _Tuple

    def _Name(self, node):
        name, scope = node.id, self.scope
        if name in scope.vars or name in scope.params or name in CONSTS:
            return
        if name == "via":
            if scope.refusal:
                return
            self.fail("`via` (the action being taken) only means something inside a refusal")
        if name == "was":
            self.fail("write `was.<var>` for a value before the move"
                      if scope.refusal else "`was.` only means something inside a refusal")
        if name in FUNCS:
            self.fail(f"`{name}` must be called, like {name}(a, b)")
        if name in scope.symbols():
            self.fail(f"`{name}` is a value, not a name; write it in quotes: \"{name}\"")
        self.fail(f"unknown name `{name}`{suggest(name, scope.names())}")

    def _Attribute(self, node):
        if not _is_was(node):
            self.fail(f"`{ast.unparse(node)}`: the only dotted name is was.<var>")
        if not self.scope.refusal:
            self.fail("`was.` only means something inside a refusal")
        if node.attr not in self.scope.vars:
            self.fail(f"`was.{node.attr}`: no var `{node.attr}`{suggest(node.attr, self.scope.vars)}")

    def _Call(self, node):
        if not (isinstance(node.func, ast.Name) and node.func.id in FUNCS) or node.keywords:
            self.fail(f"`{ast.unparse(node)}`: only min(), max() and abs() can be called")
        if not node.args:
            self.fail(f"`{ast.unparse(node)}` needs something to work on")
        for arg in node.args:
            self.check(arg)

    def _literals(self, left, op, right):
        if isinstance(op, (ast.Eq, ast.NotEq)):
            for named, other in ((left, right), (right, left)):
                domain = self.scope.domain_of(named)
                if domain is not None and isinstance(other, ast.Constant):
                    self._member(named, other.value, domain)
        elif isinstance(op, (ast.In, ast.NotIn)):
            domain = self.scope.domain_of(left)
            if domain is not None and isinstance(right, (ast.Set, ast.Tuple, ast.List)):
                for elt in right.elts:
                    if isinstance(elt, ast.Constant):
                        self._member(left, elt.value, domain)

    def _textual(self, node):
        """Does this hold a name rather than a number, as far as can be seen?"""
        if isinstance(node, ast.Constant):
            return isinstance(node.value, str)
        if isinstance(node, ast.IfExp):
            return self._textual(node.body) or self._textual(node.orelse)
        if isinstance(node, ast.Call):
            return any(self._textual(arg) for arg in node.args)
        domain = self.scope.domain_of(node)
        return domain is not None and isinstance(domain[0], str)

    def _member(self, node, value, domain):
        if in_domain(value, domain):
            return
        shown, hint = fmt_value(value), ""
        if isinstance(value, str):
            shown = f'"{value}"'
            hint = suggest(value, [v for v in domain if isinstance(v, str)]).replace("`", '"')
        self.fail(f"{shown} is not a value `{ast.unparse(node)}` can hold "
                  f"({describe_domain(domain)}){hint}")

"""Receipts: the visible trail by which intention travelled into the world.

Every gesture appends one line of JSON to a ledger. Each receipt carries the
hash of the one before it, so the trail can be checked end to end: a receipt
edited, removed or reordered breaks the chain at that point.
"""

from __future__ import annotations

import datetime
import hashlib
import json
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
GENESIS = "genesis"


def default_ledger():
    return Path(os.environ.get("TEND_LEDGER") or ROOT / "ledger" / "receipts.jsonl")


def _digest(receipt):
    body = {k: v for k, v in receipt.items() if k != "hash"}
    canon = json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(canon.encode("utf-8")).hexdigest()


def _where(path):
    path = Path(path).resolve()
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        return str(path)


class Ledger:
    def __init__(self, path=None):
        self.path = Path(path) if path else default_ledger()

    def read(self):
        if not self.path.exists():
            return []
        lines = self.path.read_text(encoding="utf-8").splitlines()
        return [json.loads(line) for line in lines if line.strip()]

    def append(self, result, why=None):
        world = result.get("world", {})
        receipts = self.read()
        receipt = {
            "seq": receipts[-1]["seq"] + 1 if receipts else 1,
            "at": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
            "gesture": result["gesture"],
            "world": world.get("name"),
            "file": _where(world["file"]) if world.get("file") else None,
            "world_sha": world.get("sha_after") or world.get("sha"),
            "asked": _asked(result),
            "answer": result["answer"],
            "why": " ".join(why.split()) if why else None,
            "prev": receipts[-1]["hash"] if receipts else GENESIS,
        }
        receipt["hash"] = _digest(receipt)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(receipt, ensure_ascii=False) + "\n")
        return receipt

    def verify(self):
        """Walk the chain. Returns (intact, count, message)."""
        try:
            receipts = self.read()
        except json.JSONDecodeError as exc:
            return False, 0, f"line {exc.lineno} of the ledger is not a receipt"
        prev = GENESIS
        for n, receipt in enumerate(receipts, 1):
            if receipt.get("seq") != n:
                return False, n, f"receipt {n} is numbered {receipt.get('seq')}: one is missing or moved"
            if receipt.get("prev") != prev:
                return False, n, f"receipt #{n} does not follow from the one before it"
            if _digest(receipt) != receipt.get("hash"):
                return False, n, f"receipt #{n} was changed after it was written"
            prev = receipt["hash"]
        if not receipts:
            return True, 0, "no receipts yet"
        return True, len(receipts), f"intact: {len(receipts)} receipts, head {prev[:12]}"


ASKED = {
    "probe": {"question": "question"},
    "chisel": {"constraint": "constraint", "carved": "carved"},
    "lean": {"name": "boundary"},
    "rehearse": {"runs": "runs", "steps": "steps", "seed": "seed"},
    "zoom": {"where": "where"},
}


def _asked(result):
    keys = ASKED.get(result["gesture"], {})
    return {label: result[key] for key, label in keys.items() if key in result}

"""Text for people. (Machines can ask for --json and read the same data.)"""

from __future__ import annotations

import textwrap

from .values import fmt_state, fmt_value, fmt_diff

PAD = "  "
LABEL = 12


def render(result):
    return {"survey": survey, "check": check, "probe": probe, "chisel": chisel,
            "lean": lean, "rehearse": rehearse, "zoom": zoom,
            "new": lambda r: r["answer"]}[result["gesture"]](result)


def header(world):
    title = world["name"] + (f" — {world['about']}" if world["about"] else "")
    lines = textwrap.wrap(title, 88, subsequent_indent=PAD)
    return lines + [f"{PAD}{world['file']} · sha {world['sha']}", ""]


def row(label, text):
    return f"{PAD}{label:<{LABEL}}{text}"


def trace_lines(trace, indent=6):
    pad = " " * indent
    width = max([len(step["via"]) for step in trace[1:]] + [0])
    lines, before = [], None
    for i, step in enumerate(trace):
        if before is None:
            lines.append(f"{pad}{i:>2}  {fmt_state(step['state'])}")
        else:
            lines.append(f"{pad}{i:>2}  {step['via']:<{width}}  {fmt_diff(before, step['state'])}")
        before = step["state"]
    return lines


def _steps(trace):
    n = len(trace) - 1
    return f"{n} step" if n == 1 else f"{n} steps"


def survey(r):
    out = header(r["world"])
    s = r["space"]
    out.append(row("space", f"{s['vars']} vars · {s['conceivable']:,} conceivable · "
                            f"{s['initial']:,} initial · {s['reachable']:,} reachable · "
                            f"depth {s['depth']} · {s['moves']:,} moves"))
    if not r["complete"]:
        out.append(row("", "unfinished: the limit was reached; counts are lower bounds"))
    if r["actions"]:
        out.append(row("actions", " · ".join(f"{a} {n}" for a, n in r["actions"].items())))
    else:
        out.append(row("actions", "none: nothing in this world moves"))
    if r["dead"]:
        out.append(row("", "never fire: " + ", ".join(r["dead"])))
    st = r["still"]
    if st["total"] == 0:
        out.append(row("still", "none: every state can move"))
    elif st["stuck"] == 0:
        out.append(row("still", f"{st['total']} {'state' if st['total'] == 1 else 'states'}, all at rest"))
    else:
        walled = f" (walled in by {', '.join(st['walled_by'])})" if st["walled_by"] else ""
        out.append(row("still", f"{st['total']} {'state' if st['total'] == 1 else 'states'} · "
                                f"{st['at_rest']} at rest · {st['stuck']} stuck; "
                                f"shortest stuck{walled}:"))
        out.extend(trace_lines(st["stuck_trace"], indent=LABEL + 4))
    if r["breaches"]:
        b = r["breaches"][0]
        out.append(row("breaches", f"{b['via']} would set {b['var']} to {fmt_value(b['value'])}, "
                                   "outside its domain, after:"))
        out.extend(trace_lines(b["trace"], indent=LABEL + 4))
    first = True
    for beam in r["beams"]:
        label = "beams" if first else ""
        first = False
        if beam["holds"]:
            out.append(row(label, f"✓ {beam['name']}"))
        else:
            out.append(row(label, f"✗ {beam['name']} breaks in {_steps(beam['trace'])}:"))
            out.extend(trace_lines(beam["trace"], indent=LABEL + 4))
    if not r["beams"]:
        out.append(row("beams", "none declared"))
    width = max([len(x["name"]) for x in r["boundaries"] + r["probes"]] + [0]) + 2
    for i, b in enumerate(r["boundaries"]):
        label = "boundaries" if i == 0 else ""
        if b["status"] == "load-bearing":
            text = f"load-bearing: holds up {', '.join(b['holds_up'])} · pressed {b['pressed']}×"
        elif b["status"] == "pressed":
            text = f"pressed {b['pressed']}×, holds up no beam (keeps out {b['keeps_out']} states)"
        else:
            text = "untouched: nothing presses on it"
        out.append(row(label, f"{b['name']:<{width}}{text}"))
    for i, p in enumerate(r["probes"]):
        label = "probes" if i == 0 else ""
        if p["reachable"]:
            text = f"reachable in {p['steps']} step{'s' if p['steps'] != 1 else ''}"
        elif p["reachable"] is False:
            text = "never"
        else:
            text = "not yet seen (unfinished)"
        out.append(row(label, f"{p['name']:<{width}}{text}"))
    return "\n".join(out)


def check(r):
    w = r["world"]
    mark = {"holds": "✓", "breaks": "✗", "unfinished": "…"}[r["verdict"]]
    out = [f"{mark} {w['name']}  {r['answer']}   ({w['file']})"]
    for beam in r["broken"]:
        out.append(f"{PAD}beam {beam['name']} breaks in {_steps(beam['trace'])}:")
        out.extend(trace_lines(beam["trace"]))
    for stuck in r["stuck"]:
        walls = f", walled in by {', '.join(stuck['walled_by'])}" if stuck["walled_by"] else ""
        out.append(f"{PAD}stuck (not at rest{walls}) after {_steps(stuck['trace'])}:")
        out.extend(trace_lines(stuck["trace"]))
    for b in r["breaches"]:
        out.append(f"{PAD}{b['via']} would set {b['var']} to {fmt_value(b['value'])}, "
                   "outside its domain, after:")
        out.extend(trace_lines(b["trace"]))
    return "\n".join(out)


def probe(r):
    out = header(r["world"])
    out.append(row("question", r["question"]))
    out.append(row("answer", r["answer"]))
    if r["trace"]:
        out.append("")
        out.extend(trace_lines(r["trace"], indent=4))
    return "\n".join(out)


def chisel(r):
    out = header(r["world"])
    b, a = r["before"], r["after"]
    out.append(row("chisel", r["constraint"]))
    out.append(row("initial", f"{b['initial']} → {a['initial']}"))
    out.append(row("reachable", f"{b['reachable']} → {a['reachable']}"))
    if r["changes"]:
        out.append(row("falls away", r["changes"][0]))
        out.extend(row("", c) for c in r["changes"][1:])
    else:
        out.append(row("falls away", "no beam, probe or action changes its answer"))
    if a["initial"] == 0:
        out.append(row("refused", "this chisel would cut away every beginning; nothing was carved"))
    elif r["carved"]:
        out.append(row("carved", f"into {r['world']['file']} (sha now {r['world']['sha_after']})"))
    else:
        out.append(row("", "(a rehearsal of the cut; add --carve to make it)"))
    return "\n".join(out)


def lean(r):
    out = header(r["world"])
    out.append(row("boundary", f"{r['name']} — {r['reason']}"))
    out.append(row("verdict", r["answer"]))
    fp = r["first_press"]
    if fp:
        when = "at the start" if len(fp["trace"]) == 1 else f"after {_steps(fp['trace'])}"
        out.append(row("first press", f"{when}, it turned away {fp['via']}:"))
        out.extend(trace_lines(fp["trace"], indent=LABEL + 4))
        out.append(" " * (LABEL + 4) + f"    ✋ {fp['via']} → {fmt_state(fp['would_become'])}")
    if r["without_trace"]:
        out.append(row("without it", f"{r['holds_up'][0]} breaks like this:"))
        out.extend(trace_lines(r["without_trace"], indent=LABEL + 4))
    if not r.get("complete", True):
        out.append(row("", "(unfinished: the limit was reached; the verdict is provisional)"))
    return "\n".join(out)


def rehearse(r):
    out = header(r["world"])
    ends = ", ".join(f"{k} {v}" for k, v in sorted(r["ends"].items())) or "—"
    out.append(row("rehearsal", f"{r['runs']} runs × up to {r['steps']} steps · seed {r['seed']}"))
    out.append(row("walked", f"{r['visited']} distinct states · mean length "
                             f"{r['lengths']['mean']} · longest {r['lengths']['max']}"))
    out.append(row("endings", ends))
    out.append(row("actions", " · ".join(f"{a} {n}" for a, n in r["actions"].items()) or "—"))
    if r["pressed"]:
        out.append(row("pressed", " · ".join(f"{a} {n}" for a, n in r["pressed"].items())))
    if r["probes"]:
        out.append(row("probes", " · ".join(f"{p} in {n} runs" for p, n in r["probes"].items())))
    if not r["breaks"] and not r["breaches"]:
        out.append(row("beams", "no break seen (a rehearsal is not a proof; `check` is)"))
    for name, found in sorted(r["breaks"].items()):
        out.append(row("broke", f"{name} in run {found['run']} after {_steps(found['trace'])}:"))
        out.extend(trace_lines(found["trace"], indent=LABEL + 4))
    for b in r["breaches"][:1]:
        out.append(row("breach", f"{b['via']} would set {b['var']} to {fmt_value(b['value'])} "
                                 f"in run {b['run']}"))
    return "\n".join(out)


def zoom(r):
    out = header(r["world"])
    out.append(row("zoom", r["where"]))
    if not r["found"]:
        out.append(row("answer", r["answer"]))
        return "\n".join(out)
    out.append(row("reached", f"in {_steps(r['trace'])}:"))
    out.extend(trace_lines(r["trace"], indent=LABEL + 4))
    out.append(row("here", fmt_state(r["here"]) + ("   (at rest)" if r["at_rest"] else "")))
    if r["beams_false"]:
        out.append(row("", "✗ false here: " + ", ".join(r["beams_false"])))
    if r["probes_true"]:
        out.append(row("", "true here: " + ", ".join(r["probes_true"])))
    width = max([len(m["via"]) for m in r["moves"]] + [0]) + 2
    lines = []
    for m in r["moves"]:
        if m["status"] == "free":
            lines.append(f"→ {m['via']:<{width}}{fmt_diff(r['here'], m['to'])}")
        elif m["status"] == "refused":
            lines.append(f"✋ {m['via']:<{width}}{fmt_diff(r['here'], m['to'])}   "
                         f"refused by {m['by']}: {m['reason']}")
        else:
            lines.append(f"! {m['via']:<{width}}would set {m['var']} to "
                         f"{fmt_value(m['value'])}, outside its domain")
    if not lines:
        lines = ["nothing is enabled here"]
    out.append(row("moves", lines[0]))
    out.extend(row("", line) for line in lines[1:])
    if r["disabled"]:
        out.append(row("disabled", ", ".join(r["disabled"])))
    return "\n".join(out)

"""How values look, and which values a domain admits."""


def fmt_value(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def fmt_state(state):
    return " ".join(f"{name}={fmt_value(value)}" for name, value in state.items())


def fmt_diff(before, after):
    changed = [
        f"{name} {fmt_value(before[name])}→{fmt_value(value)}"
        for name, value in after.items()
        if before[name] != value or type(before[name]) is not type(value)
    ]
    return ", ".join(changed) if changed else "(no change)"


def describe_domain(domain):
    first = domain[0]
    if isinstance(first, bool):
        return "bool"
    if isinstance(first, int) and len(domain) >= 2:
        if list(domain) == list(range(domain[0], domain[-1] + 1)):
            return f"{domain[0]}..{domain[-1]}"
    return "{" + ", ".join(fmt_value(v) for v in domain) + "}"


def in_domain(value, domain):
    # bool is an int in Python; a world keeps them apart.
    return any(type(value) is type(item) and value == item for item in domain)

"""World files: reading, checking, and the compiled form the bench explores.

A world file is a list of declarations, one per line. An indented line
continues the declaration above it; `#` begins a comment.

    world NAME
    about TEXT
    var NAME in bool | LO..HI | {a, b, c}
    init EXPR
    action NAME[(P in DOMAIN, ...)]: [GUARD] -> VAR = EXPR, ... | skip
    beam NAME: EXPR
    refuse NAME: EXPR because "REASON"
    probe NAME: EXPR
    rest NAME: EXPR
"""

from __future__ import annotations

import difflib
import hashlib
import itertools
import keyword
import math
import re
from pathlib import Path

from .errors import WorldError
from .expr import RESERVED, Scope, compile_expr, literal_outcomes, suggest
from .values import describe_domain, fmt_value, in_domain

KINDS = ("world", "about", "var", "init", "action", "beam", "refuse", "probe", "rest")
IDENT = r"[A-Za-z_][A-Za-z0-9_]*"
SYMBOL = r"[A-Za-z_][A-Za-z0-9_-]*"
DOMAIN_LIMIT = 10_000      # values one var may hold
ENUM_LIMIT = 2_000_000     # conceivable states the bench will sift for initial ones


class Var:
    def __init__(self, name, domain, line):
        self.name, self.domain, self.line = name, domain, line
        self._type = type(domain[0])
        self._values = frozenset(domain)

    def accepts(self, value):
        return type(value) is self._type and value in self._values


class Action:
    def __init__(self, name, params, guard, assigns, line):
        self.name = name
        self.params = params      # [(name, domain)]
        self.guard = guard        # Expr, or None for "always"
        self.assigns = assigns    # [(var index, Expr)], applied simultaneously
        self.line = line
        self.instances = []       # [(label, param env)]
        names = [p for p, _ in params]
        for combo in itertools.product(*(d for _, d in params)):
            env = dict(zip(names, combo))
            label = name
            if env:
                label += "(" + ", ".join(f"{k}={fmt_value(v)}" for k, v in env.items()) + ")"
            self.instances.append((label, env))


class Rule:
    """A named judgement over states: a beam, refusal, probe or rest."""

    def __init__(self, kind, name, expr, line, reason=None):
        self.kind, self.name, self.expr, self.line, self.reason = kind, name, expr, line, reason


class World:
    def __init__(self, path, text):
        self.path = str(path)
        self.text = text
        self.sha = hashlib.sha256(text.encode("utf-8")).hexdigest()
        self.name = Path(path).stem
        self.about = []
        self.vars = []
        self.inits = []
        self.actions = []
        self.beams = []
        self.refusals = []
        self.probes = []
        self.rests = []
        self._names = ()

    @property
    def description(self):
        return " ".join(self.about)

    @property
    def conceivable(self):
        return math.prod(len(v.domain) for v in self.vars)

    def env(self, state):
        return dict(zip(self._names, state))

    show = env

    def scope(self, refusal=False, params=None):
        return Scope({v.name: v.domain for v in self.vars}, params, refusal)

    def compile(self, src, what):
        """Compile an expression offered by a gesture rather than the file."""
        return compile_expr(src, self.scope(), what)

    def rule(self, kind, name):
        rules = {"refusal": self.refusals, "probe": self.probes, "beam": self.beams}[kind]
        for rule in rules:
            if rule.name == name:
                return rule
        names = [r.name for r in rules]
        known = ", ".join(names) if names else "none"
        raise WorldError(f"{self.name} has no {kind} `{name}`{suggest(name, names)}; "
                         f"its {kind}s: {known}")

    def initial_states(self, extra=()):
        if self.conceivable > ENUM_LIMIT:
            raise WorldError(
                f"{self.name} can be {self.conceivable:,} different ways before any action; "
                f"the bench sifts at most {ENUM_LIMIT:,}. Narrow some domains.", self.path)
        tests = list(self.inits) + list(extra)
        found = []
        for combo in itertools.product(*(v.domain for v in self.vars)):
            env = self.env(combo)
            if all(t.test(env) for t in tests):
                found.append(combo)
        return found


def load_world(path):
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise WorldError(f"cannot open world: {exc.strerror}", str(path)) from None
    return parse_world(text, str(path))


def parse_world(text, path="<world>"):
    world = World(path, text)
    later = []
    taken = {}

    def claim(name, what, line):
        if name in taken:
            raise WorldError(f"`{name}` is already the name of {taken[name]}", path, line)
        taken[name] = what

    for line, kind, rest in _declarations(text, path):
        if kind == "world":
            if not rest or " " in rest:
                raise WorldError("write: world NAME (one word)", path, line)
            world.name = rest
        elif kind == "about":
            world.about.append(rest)
        elif kind == "var":
            world.vars.append(_parse_var(rest, path, line, taken))
        else:
            later.append((line, kind, rest))

    if not world.vars:
        raise WorldError("a world needs at least one var", path)
    world._names = tuple(v.name for v in world.vars)
    index = {v.name: i for i, v in enumerate(world.vars)}

    for line, kind, rest in later:
        if kind == "init":
            world.inits.append(compile_expr(rest, world.scope(), "init", path, line))
        elif kind == "action":
            action = _parse_action(rest, world, index, path, line)
            claim(action.name, "an action", line)
            world.actions.append(action)
        else:
            rule = _parse_rule(kind, rest, world, path, line)
            claim(rule.name, f"a {kind}", line)
            {"beam": world.beams, "refuse": world.refusals,
             "probe": world.probes, "rest": world.rests}[kind].append(rule)
    return world


def split_top(text, sep, maxsplit=-1, word=False):
    """Split on `sep` where it stands outside quotes and brackets."""
    parts, depth, quote, start, i = [], 0, None, 0, 0
    while i < len(text):
        ch = text[i]
        if quote:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        elif (depth == 0 and text.startswith(sep, i)
              and (maxsplit < 0 or len(parts) < maxsplit)
              and (not word or (_edge(text, i - 1) and _edge(text, i + len(sep))))):
            parts.append(text[start:i])
            i += len(sep)
            start = i
            continue
        i += 1
    parts.append(text[start:])
    return parts


def _edge(text, i):
    return i < 0 or i >= len(text) or not (text[i].isalnum() or text[i] == "_")


def _strip_comment(text, plain):
    if plain:
        return text.split("#", 1)[0].strip()
    quote = None
    for i, ch in enumerate(text):
        if quote:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch == "#":
            return text[:i].strip()
    return text.strip()


def _declarations(text, path):
    current = None
    for line, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if raw[0] in " \t":
            if current is None:
                raise WorldError("an indented line continues a declaration, "
                                 "but none came before it", path, line)
            more = _strip_comment(stripped, current[1] == "about")
            if more:
                current[2] = f"{current[2]} {more}".strip()
            continue
        if current:
            yield tuple(current)
        kind, _, rest = stripped.partition(" ")
        if kind not in KINDS:
            close = difflib.get_close_matches(kind, KINDS, n=1)
            hint = f" (did you mean `{close[0]}`?)" if close else ""
            raise WorldError(f"`{kind}` does not begin a declaration{hint}; "
                             f"the words are: {', '.join(KINDS)}", path, line)
        current = [line, kind, _strip_comment(rest, kind == "about")]
    if current:
        yield tuple(current)


def _check_name(name, what, path, line):
    if not re.fullmatch(IDENT, name):
        raise WorldError(f"`{name}` cannot name {what}; use letters, digits and _", path, line)
    if keyword.iskeyword(name) or name in RESERVED:
        raise WorldError(f"`{name}` is already a word in the language; "
                         f"choose another name for {what}", path, line)


def parse_domain(src, path=None, line=None):
    src = src.strip()
    if src == "bool":
        return (False, True)
    span = re.fullmatch(r"(-?\d+)\s*\.\.\s*(-?\d+)", src)
    if span:
        lo, hi = int(span.group(1)), int(span.group(2))
        if lo > hi:
            raise WorldError(f"the range {lo}..{hi} is empty", path, line)
        if hi - lo + 1 > DOMAIN_LIMIT:
            raise WorldError(f"{lo}..{hi} holds {hi - lo + 1:,} values; "
                             f"a var may hold at most {DOMAIN_LIMIT:,}", path, line)
        return tuple(range(lo, hi + 1))
    if src.startswith("{") and src.endswith("}"):
        values = []
        for item in (x.strip() for x in split_top(src[1:-1], ",")):
            if re.fullmatch(r"-?\d+", item):
                values.append(int(item))
            elif re.fullmatch(SYMBOL, item) or re.fullmatch(r"\"[^\"]+\"|'[^']+'", item):
                value = item.strip("\"'")
                if value in RESERVED or keyword.iskeyword(value):
                    raise WorldError(f"`{value}` is already a word in the language; "
                                     "for a true/false var, write `in bool`", path, line)
                values.append(value)
            else:
                raise WorldError(f"cannot read `{item}` in domain {src}", path, line)
        if not values:
            raise WorldError("an empty domain leaves nothing to be", path, line)
        if len({type(v) for v in values}) > 1:
            raise WorldError(f"{src} mixes numbers and names; a domain holds one kind", path, line)
        if len(set(values)) != len(values):
            raise WorldError(f"{src} names a value twice", path, line)
        return tuple(values)
    raise WorldError(f"cannot read domain `{src}`; write bool, LO..HI, or {{a, b, c}}",
                     path, line)


def _parse_var(rest, path, line, taken):
    match = re.fullmatch(r"(\S+)\s+in\s+(.+)", rest)
    if not match:
        raise WorldError("write: var NAME in DOMAIN", path, line)
    name = match.group(1)
    _check_name(name, "a var", path, line)
    if name in taken:
        raise WorldError(f"var `{name}` is declared twice", path, line)
    taken[name] = "a var"
    return Var(name, parse_domain(match.group(2), path, line), line)


def _parse_action(rest, world, index, path, line):
    match = re.fullmatch(rf"({IDENT})\s*(?:\((.*?)\))?\s*:\s*(.*)", rest)
    if not match:
        raise WorldError("write: action NAME: GUARD -> VAR = EXPR, ...", path, line)
    name, param_src, body = match.groups()
    _check_name(name, "an action", path, line)

    params = []
    for item in split_top(param_src or "", ","):
        if not item.strip():
            continue
        pm = re.fullmatch(r"\s*(\S+)\s+in\s+(.+)", item)
        if not pm:
            raise WorldError(f"cannot read parameter `{item.strip()}`; write NAME in DOMAIN",
                             path, line)
        pname = pm.group(1)
        _check_name(pname, "a parameter", path, line)
        if pname in index or pname in dict(params):
            raise WorldError(f"parameter `{pname}` hides another name", path, line)
        params.append((pname, parse_domain(pm.group(2), path, line)))

    halves = split_top(body, "->", maxsplit=1)
    if len(halves) != 2:
        raise WorldError(f"action {name} needs `->` between its guard and its changes",
                         path, line)
    guard_src, change_src = (h.strip() for h in halves)
    scope = world.scope(params=dict(params))
    guard = None
    if guard_src:
        guard = compile_expr(guard_src, scope, f"guard of {name}", path, line)

    assigns = []
    if change_src != "skip":
        for item in split_top(change_src, ","):
            am = re.fullmatch(rf"\s*({IDENT})\s*=(?!=)\s*(.+)", item, re.S)
            if not am:
                raise WorldError(f"cannot read change `{item.strip()}` in {name}; "
                                 "write VAR = EXPR (or `skip` for none)", path, line)
            var, src = am.groups()
            if var not in index:
                raise WorldError(f"{name} changes `{var}`, which is not a var"
                                 f"{suggest(var, index)}", path, line)
            if any(i == index[var] for i, _ in assigns):
                raise WorldError(f"{name} changes `{var}` twice", path, line)
            expr = compile_expr(src, scope, f"change to {var} in {name}", path, line)
            domain = world.vars[index[var]].domain
            for value in literal_outcomes(expr.tree):
                if not in_domain(value, domain):
                    shown = f'"{value}"' if isinstance(value, str) else fmt_value(value)
                    raise WorldError(f"{name} would set {var} to {shown}, which it cannot hold "
                                     f"({describe_domain(domain)})", path, line)
            assigns.append((index[var], expr))
    return Action(name, params, guard, assigns, line)


def _parse_rule(kind, rest, world, path, line):
    match = re.fullmatch(rf"(\S+?)\s*:\s*(.*)", rest)
    if not match:
        raise WorldError(f"write: {kind} NAME: EXPR"
                         + (' because "REASON"' if kind == "refuse" else ""), path, line)
    name, body = match.groups()
    _check_name(name, f"a {kind}", path, line)
    reason = None
    if kind == "refuse":
        parts = split_top(body, "because", maxsplit=1, word=True)
        if len(parts) != 2 or not parts[1].strip():
            raise WorldError(f"refusal {name} needs a reason: "
                             f'refuse {name}: EXPR because "REASON"', path, line)
        body, reason = parts[0], parts[1].strip()
        if len(reason) >= 2 and reason[0] == reason[-1] and reason[0] in "\"'":
            reason = reason[1:-1]
    what = {"refuse": "refusal"}.get(kind, kind) + f" {name}"
    expr = compile_expr(body, world.scope(refusal=kind == "refuse"), what, path, line)
    return Rule(kind, name, expr, line, reason)
